export function createRateLimiter() {
  const config = {
    maxRequests: 3,
    windowMs: 1000
  };

  const state = new Map<string, { count: number; windowStart: number }>();

  function allow(key: string, nowMs: number): boolean {
    const current = state.get(key);

    // If no state exists or window has elapsed, reset
    if (!current || nowMs - current.windowStart >= config.windowMs) {
      state.set(key, { count: 1, windowStart: nowMs });
      return true;
    }

    // Within the window, check if we can still make requests
    if (current.count < config.maxRequests) {
      current.count++;
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const current = state.get(key);

    // If no state exists or window has elapsed, return full quota
    if (!current || nowMs - current.windowStart >= config.windowMs) {
      return config.maxRequests;
    }

    return Math.max(0, config.maxRequests - current.count);
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, remaining, reset };
}
