export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      const expiresAt = nowMs + ttlMs;
      cache.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      const entry = cache.get(key);
      return entry?.expiresAt >= nowMs ? entry.value : undefined;
    },
    has(key, nowMs) {
      const entry = cache.get(key);
      return entry?.expiresAt >= nowMs;
    },
    delete(key) {
      return cache.delete(key);
    },
    size(nowMs) {
      return Array.from(cache.entries()).filter(
        ([_, entry]) => entry.expiresAt >= nowMs
      ).length;
    },
    clear() {
      cache.clear();
    },
  };
}

