export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs) {
      if (typeof ttlMs === 'undefined') {
        ttlMs = 1000; // Default TTL is 1000ms
      }
      cache.set(key, { value, expiresAt: nowMs + ttlMs });
    },
    get(key, nowMs) {
      const item = cache.get(key);
      if (!item || item.expiresAt <= nowMs) return undefined;
      return item.value;
    },
    has(key, nowMs) {
      const item = cache.get(key);
      return Boolean(item && item.expiresAt > nowMs);
    },
    delete(key) {
      return cache.delete(key);
    },
    size(nowMs) {
      let liveEntriesCount = 0;
      for (const [key, { expiresAt }] of cache.entries()) {
        if (expiresAt > nowMs) liveEntriesCount++;
      }
      return liveEntriesCount;
    },
    clear() {
      cache.clear();
    },
  };
}
