type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

type ListenerEntry = {
  listener: Listener;
  once: boolean;
};

export function createEventEmitter(): EventEmitter {
  const _listeners = new Map<string, ListenerEntry[]>();

  return {
    on(event, listener) {
      let listeners = _listeners.get(event);
      if (!listeners) {
        listeners = [];
        _listeners.set(event, listeners);
      }
      listeners.push({ listener, once: false });
      return listeners.length;
    },
    once(event, listener) {
      let listeners = _listeners.get(event);
      if (!listeners) {
        listeners = [];
        _listeners.set(event, listeners);
      }
      listeners.push({ listener, once: true });
      return listeners.length;
    },
    off(event, listener) {
      const listeners = _listeners.get(event);
      if (!listeners) return false;
      for (let i = 0; i < listeners.length; i++) {
        if (listeners[i].listener === listener) {
          listeners.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event, payload) {
      const listeners = _listeners.get(event) || [];
      const results: unknown[] = [];
      let i = 0;
      while (i < listeners.length) {
        const listenerEntry = listeners[i];
        const result = listenerEntry.listener(payload);
        results.push(result);
        if (listenerEntry.once) {
          listeners.splice(i, 1);
        } else {
          i++;
        }
      }
      return results;
    },
    listenerCount(event) {
      const listeners = _listeners.get(event);
      return listeners ? listeners.length : 0;
    },
  };
