interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const map = new Map<string, { windowStart: number; remaining: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let state = map.get(key);
      if (!state) {
        state = { windowStart: nowMs - (nowMs % windowMs), remaining: limit };
        map.set(key, state);
      } else {
        if (nowMs - state.windowStart >= windowMs) {
          state.windowStart = nowMs - (nowMs % windowMs);
          state.remaining = limit;
        }
      }
      if (state.remaining > 0) {
        state.remaining -= 1;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      let state = map.get(key);
      if (!state) {
        state = { windowStart: nowMs - (nowMs % windowMs), remaining: limit };
        map.set(key, state);
      } else {
        if (nowMs - state.windowStart >= windowMs) {
          state.windowStart = nowMs - (nowMs % windowMs);
          state.remaining = limit;
        }
      }
      return state.remaining;
    },
    reset(key: string): void {
      map.delete(key);
    }
  };
}
