type ListenerRecord = {
  fn: (...args: any[]) => any;
  once: boolean;
};

function createEventEmitter() {
  const events = new Map<string, ListenerRecord[]>();

  function on(event: string, listener: (...args: any[]) => any): number {
    let listeners = events.get(event);
    if (!listeners) {
      listeners = [];
      events.set(event, listeners);
    }
    listeners.push({ fn: listener, once: false });
    return listeners.length;
  }

  function once(event: string, listener: (...args: any[]) => any): number {
    let listeners = events.get(event);
    if (!listeners) {
      listeners = [];
      events.set(event, listeners);
    }
    listeners.push({ fn: listener, once: true });
    return listeners.length;
  }

  function off(event: string, listener: (...args: any[]) => any): boolean {
    const listeners = events.get(event);
    if (!listeners) return false;
    for (let i = 0; i < listeners.length; i++) {
      if (listeners[i].fn === listener) {
        listeners.splice(i, 1);
        if (listeners.length === 0) {
          events.delete(event);
        }
        return true;
      }
    }
    return false;
  }

  function emit(event: string, payload: any): any[] {
    const listeners = events.get(event);
    if (!listeners) return [];
    const results: any[] = [];

    // Snapshot to allow safe modifications during iteration
    for (const listenerObj of [...listeners]) {
      const result = listenerObj.fn(payload);
      results.push(result);
      if (listenerObj.once) {
        const idx = listeners.indexOf(listenerObj);
        if (idx !== -1) {
          listeners.splice(idx, 1);
        }
      }
    }

    if (listeners.length === 0) {
      events.delete(event);
    }

    return results;
  }

  function listenerCount(event: string): number {
    const listeners = events.get(event);
    return listeners ? listeners.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}

