        emit(event: string, payload: unknown): unknown[] {
            const listeners = map.get(event);
            if (!listeners || listeners.length === 0) {
                return [];
            }
            const results: unknown[] = [];
            for (const entry of listeners) {
                results.push(entry.listener(payload));
            }
            const remaining = listeners.filter(entry => !entry.once);
            if (remaining.length > 0) {
                map.set(event, remaining);
            } else {
                map.delete(event);
            }
            return results;
        },
        listenerCount(event: string): number {
            const listeners = map.get(event);
            return listeners ? listeners.length : 0;
        }
    };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
    on(event: string, listener: Listener): number
    once(event: string, listener: Listener): number
    off(event: string, listener: Listener): boolean
    emit(event: string, payload: unknown): unknown[]
    listenerCount(event: string): number
}

export function createRateLimiter() {
    const MAX_REQUESTS = 3;
    const WINDOW_MS = 1000;

    const stateMap = new Map<string, { count: number; startTime: number }>();

    const allow = (key: string, nowMs: number): boolean => {
        let record = stateMap.get(key);
        if (!record) {
            // First request for this key
            record = { count: 1, startTime: nowMs };
            stateMap.set(key, record);
            return true;
        }

        if (nowMs - record.startTime >= WINDOW_MS) {
            // Window elapsed; reset usage and start time
            record.count = 0;
            record.startTime = nowMs;
        }

        if (record.count < MAX_REQUESTS) {
            record.count++;
            return true;
        }
        return false;
    };

    const remaining = (key: string, nowMs: number): number => {
        let record = stateMap.get(key);
        if (!record) {
            return MAX_REQUESTS;
        }

        if (nowMs - record.startTime >= WINDOW_MS) {
            // Window elapsed; reset usage and start time
            record.count = 0;
            record.startTime = nowMs;
        }

        return Math.max(MAX_REQUESTS - record.count, 0);
    };

    const reset = (key: string): void => {
        stateMap.delete(key);
    };

    return { allow, remaining, reset };
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const store = new Map<string, { count: number; start: number }>();

  const getRecord = (key: string, now: number): { count: number; start: number } => {
    let rec = store.get(key);
    if (!rec) {
      rec = { count: 0, start: now };
      store.set(key, rec);
    }
    if (now - rec.start >= windowMs) {
      rec.count = 0;
      rec.start = now;
    }
    return rec;
  };

  const allow = (key: string, nowMs: number): boolean => {
    const rec = getRecord(key, nowMs);
    if (rec.count < limit) {
      rec.count++;
      return true;
    }
    return false;
  };

  const remaining = (key: string, nowMs: number): number => {
    const rec = getRecord(key, nowMs);
    return rec.count < limit ? limit - rec.count : 0;
  };

  const reset = (key: string): void => {
    store.delete(key);
  };

  return { allow, remaining, reset };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

