export function createTodoApp() {
    let nextId = 1;
    const todos = new Map<number, { id: number; text: string; completed: boolean }>();

    return {
        addTodo(text: string): { id: number; text: string; completed: boolean } {
            const todo: { id: number; text: string; completed: boolean } = {
                id: nextId++,
                text,
                completed: false,
            };
            todos.set(todo.id, todo);
            return todo;
        },

        getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
            return todos.get(id);
        },

        toggleTodo(id: number): void {
            const todo = todos.get(id);
            if (todo) {
                todo.completed = !todo.completed;
            }
        },

        deleteTodo(id: number): boolean {
            return todos.delete(id);
        },

        listTodos(): Array<{ id: number; text: string; completed: boolean }> {
            return Array.from(todos.values());
        },

        listCompleted(): Array<{ id: number; text: string; completed: boolean }> {
            const result = [];
            for (const todo of todos.values()) {
                if (todo.completed) result.push(todo);
            }
            return result;
        },

        listPending(): Array<{ id: number; text: string; completed: boolean }> {
            const result = [];
            for (const todo of todos.values()) {
                if (!todo.completed) result.push(todo);
            }
            return result;
        },

        clearCompleted(): void {
            for (const [id, todo] of Array.from(todos.entries())) {
                if (todo.completed) {
                    todos.delete(id);
                }
            }
        },
    };
}

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

interface TodoApp {
  addTodo(text: string): Todo;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

export function createTodoApp(): TodoApp {
  let nextId = 1;
  const todos: Todo[] = [];

  const addTodo = (text: string): Todo => {
    const todo: Todo = { id: nextId++, text, completed: false };
    todos.push(todo);
    return todo;
  };

  const getTodo = (id: number): Todo | undefined => {
    return todos.find(t => t.id === id);
  };

  const toggleTodo = (id: number): void => {
    const todo = todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    const index = todos.findIndex(t => t.id === id);
    if (index !== -1) {
      todos.splice(index, 1);
      return true;
    }
    return false;
  };

  const listTodos = (): Todo[] => [
    ...todos
  ];

  const listCompleted = (): Todo[] => todos.filter(t => t.completed);

  const listPending = (): Todo[] => todos.filter(t => !t.completed);

  const clearCompleted = (): void => {
    const completedIndices: number[] = [];
    for (let i = 0; i < todos.length; i++) {
      if (todos[i].completed) {
        completedIndices.push(i);
      }
    }
    for (let i = completedIndices.length - 1; i >= 0; i--) {
      todos.splice(completedIndices[i], 1);
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}

export function createTtlCache() {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs ?? 1000;
      const expiresAt = nowMs + ttl;
      store.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number): unknown {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string): boolean {
      return store.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of store.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          store.delete(key);
        }
      }
      return count;
    },
    clear(): void {
      store.clear();
    },
  };
}

