export function createEventEmitter() {
  const events = new Map<string, Array<{ listener: Function, isOneTime: boolean }>>();

  return {
    on(event: string, listener: Function): number {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const listeners = events.get(event);
      listeners.push({ listener, isOneTime: false });
      return listeners.length;
    },
    once(event: string, listener: Function): number {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const listeners = events.get(event);
      listeners.push({ listener, isOneTime: true });
      return listeners.length;
    },
    off(event: string, listener: Function): boolean {
      if (!events.has(event)) {
        return false;
      }
      const listeners = events.get(event);
      for (let i = 0; i < listeners.length; i++) {
        const l = listeners[i];
        if (l.listener === listener) {
          listeners.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event: string, payload: any): any[] {
      if (!events.has(event)) {
        return [];
      }
      const listeners = events.get(event);
      const copy = [...listeners];
      const results: any[] = [];
      for (const listener of copy) {
        const result = listener.listener(payload);
        results.push(result);
        if (listener.isOneTime) {
          const index = listeners.indexOf(listener);
          if (index !== -1) {
            listeners.splice(index, 1);
          }
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      if (!events.has(event)) {
        return 0;
      }
      return events.get(event).length;
    }
  };
}
