  class EventEmitter {
    private listeners: Map<string, Array<{ listener: Listener, once: boolean }>> = new Map();

    on(event: string, listener: Listener): number {
      const eventListeners = this.listeners.get(event) || [];
      eventListeners.push({ listener, once: false });
      this.listeners.set(event, eventListeners);
      return eventListeners.length;
    }

    once(event: string, listener: Listener): number {
      const eventListeners = this.listeners.get(event) || [];
      eventListeners.push({ listener, once: true });
      this.listeners.set(event, eventListeners);
      return eventListeners.length;
    }

    off(event: string, listener: Listener): boolean {
      const eventListeners = this.listeners.get(event) || [];
      const index = eventListeners.findIndex(l => l.listener === listener);
      if (index !== -1) {
        eventListeners.splice(index, 1);
        return true;
      }
      return false;
    }

    emit(event: string, payload: unknown): unknown[] {
      const eventListeners = this.listeners.get(event) || [];
      const results: unknown[] = [];
      const listenersCopy = [...eventListeners];
      for (const listener of listenersCopy) {
        if (listener.once) {
          const index = eventListeners.indexOf(listener);
          if (index !== -1) {
            eventListeners.splice(index, 1);
          }
        }
        results.push(listener.listener(payload));
      }
      return results;
    }

    listenerCount(event: string): number {
      const eventListeners = this.listeners.get(event) || [];
      return eventListeners.length;
    }
  }

  return new EventEmitter();
