export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      const expiresAt = nowMs + (ttlMs || 1000);
      cache.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      const entry = cache.get(key);
      if (entry && nowMs < entry.expiresAt) {
        return entry.value;
      } else {
        cache.delete(key);
        return undefined;
      }
    },
    has(key, nowMs) {
      const entry = cache.get(key);
      return !!entry && nowMs < entry.expiresAt;
    },
    delete(key) {
      const entry = cache.get(key);
      if (entry) {
        cache.delete(key);
        return true;
      }
      return false;
    },
    size(nowMs) {
      let count = 0;
      for (const [_, entry] of cache.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
      cache.clear();
    }
  };
}
