export function createEventEmitter() {
  const eventMap = new Map<string, { listeners: Array<{ callback: Function, once: boolean }> }>();

  return {
    on(event: string, listener: Function): number {
      if (!eventMap.has(event)) {
        eventMap.set(event, { listeners: [] });
      }
      const listeners = eventMap.get(event).listeners;
      listeners.push({ callback: listener, once: false });
      return listeners.length;
    },

    once(event: string, listener: Function): number {
      if (!eventMap.has(event)) {
        eventMap.set(event, { listeners: [] });
      }
      const listeners = eventMap.get(event).listeners;
      listeners.push({ callback: listener, once: true });
      return listeners.length;
    },

    off(event: string, listener: Function): boolean {
      const listeners = eventMap.get(event)?.listeners || [];
      for (let i = 0; i < listeners.length; i++) {
        if (listeners[i].callback === listener) {
          listeners.splice(i, 1);
          return true;
        }
      }
      return false;
    },

    emit(event: string, payload: any): any[] {
      const listeners = eventMap.get(event)?.listeners || [];
      const result = [];
      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        const value = listener.callback(payload);
        if (listener.once) {
          listeners.splice(i, 1);
          i--;
        }
        result.push(value);
      }
      return result;
    },

    listenerCount(event: string): number {
      return eventMap.get(event)?.listeners?.length || 0;
    }
  };
}
