type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
  const events: Record<string, { listener: Listener; once: boolean }[]> = {}

  return {
    on(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = []
      }
      events[event].push({ listener, once: false })
      return events[event].length
    },

    once(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = []
      }
      events[event].push({ listener, once: true })
      return events[event].length
    },

    off(event: string, listener: Listener): boolean {
      const eventListeners = events[event]
      if (!eventListeners) {
        return false
      }
      const index = eventListeners.findIndex((entry) => entry.listener === listener)
      if (index === -1) {
        return false
      }
      eventListeners.splice(index, 1)
      if (eventListeners.length === 0) {
        delete events[event]
      }
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      const eventListeners = events[event]
      if (!eventListeners) {
        return []
      }
      const results: unknown[] = []
      const toCall = [...eventListeners]

      for (const entry of toCall) {
        const result = entry.listener(payload)
        results.push(result)
        if (entry.once) {
          this.off(event, entry.listener)
        }
      }

      return results
    },

    listenerCount(event: string): number {
      const eventListeners = events[event]
      return eventListeners ? eventListeners.length : 0
    }
  }
}

export { createEventEmitter }
