export function createEventEmitter() {
    type Listener = (...args: any[]) => any;
    type ListenerEntry = {
        listener: Listener;
        once: boolean;
    };

    const events: Record<string, ListenerEntry[]> = {};

    function on(event: string, listener: Listener): number {
        if (!events[event]) {
            events[event] = [];
        }
        events[event].push({ listener, once: false });
        return events[event].length;
    }

    function once(event: string, listener: Listener): number {
        if (!events[event]) {
            events[event] = [];
        }
        events[event].push({ listener, once: true });
        return events[event].length;
    }

    function off(event: string, listener: Listener): boolean {
        if (!events[event]) {
            return false;
        }

        const index = events[event].findIndex(
            (entry) => entry.listener === listener && !entry.once,
        );
        if (index === -1) {
            return false;
        }

        events[event].splice(index, 1);
        return true;
    }

    function emit(event: string, payload: any): any[] {
        if (!events[event]) {
            return [];
        }

        const eventListeners = [...events[event]];
        const results: any[] = [];

        for (const entry of eventListeners) {
            results.push(entry.listener.call(this, payload));
        }

        events[event] = events[event].filter(
            (entry) => !entry.once || entry.listener === payload,
        );

        return results;
    }

    function listenerCount(event: string): number {
        return events[event]?.length ?? 0;
    }

    return {
        on,
        once,
        off,
        emit,
        listenerCount,
    };
}
