      return events[event].length;
    },

    off(event: string, listener: Listener): boolean {
      if (!events[event]) {
        return false;
      }
      const index = events[event].findIndex((item) => item.listener === listener);
      if (index === -1) {
        return false;
      }
      events[event].splice(index, 1);
      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!events[event]) {
        return [];
      }
      const result: unknown[] = [];
      const listeners = [...events[event]]; // Create a copy to safely modify during iteration

      for (const item of listeners) {
        result.push(item.listener(payload));
        if (item.once) {
          const index = events[event].findIndex((i) => i === item);
          if (index !== -1) {
            events[event].splice(index, 1);
          }
        }
      }

      return result;
    },

    listenerCount(event: string): number {
      return events[event]?.length || 0;
    }
  };
}
