type RateLimiter = {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
};

type RateLimiterState = {
  count: number;
  windowStart: number;
};

export function createRateLimiter(): RateLimiter {
  const state: Record<string, RateLimiterState> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const current = state[key] || { count: 0, windowStart: nowMs };
      const shouldReset = nowMs - current.windowStart >= 1000;

      const newState: RateLimiterState = shouldReset
        ? { count: 1, windowStart: nowMs }
        : { ...current, count: current.count + 1 };

      state[key] = newState;

      const isAllowed = newState.count <= 3;
      return isAllowed;
    },

    remaining(key: string, nowMs: number): number {
      const current = state[key] || { count: 0, windowStart: nowMs };
      const shouldReset = nowMs - current.windowStart >= 1000;

      const resolved = shouldReset
        ? { count: 0, windowStart: nowMs }
        : current;

      return Math.max(3 - resolved.count, 0);
    },

    reset(key: string): void {
      delete state[key];
    },
  };
}
