export function createCalculator() {
    let currentValue = 0;
    let memoryValue = 0;

    const add = (n: number): Calculator => {
        currentValue += n;
        return { add, subtract, multiply, divide, clear, result, memoryStore, memoryAdd, memoryRecall, memoryClear };
    };

    const subtract = (n: number): Calculator => {
        currentValue -= n;
        return { add, subtract, multiply, divide, clear, result, memoryStore, memoryAdd, memoryRecall, memoryClear };
    };

    const multiply = (n: number): Calculator => {
        if (currentValue === 0) {
            currentValue = n;
        } else {
            currentValue *= n;
        }
        return { add, subtract, multiply, divide, clear, result, memoryStore, memoryAdd, memoryRecall, memoryClear };
    };

    const divide = (n: number): Calculator => {
        if (currentValue === 0) {
            throw new Error("Cannot set value to 0");
        } else if (n === 0) {
            throw new Error("Division by zero is undefined and cannot be performed.");
        }
        currentValue /= n;
        return { add, subtract, multiply, divide, clear, result, memoryStore, memoryAdd, memoryRecall, memoryClear };
    };

    const clear = (): Calculator => {
        currentValue = 0;
