import { EventEmitter } from "events";

interface Listener {
  listener: (...args: any[]) => void;
  once?: boolean;
}

function createEventEmitter(): {
  on(event: string, listener: (...args: any[]) => void): number;
  once(event: string, listener: (...args: any[]) => void): number;
  off(event: string, listener: (...args: any[]) => void): boolean;
  emit(event: string, ...payload: any[]): any[];
  listenerCount(event: string): number;
} {
  const ee = new EventEmitter();

  const listenersRegistry: Record<string, Listener[]> = {};

  function on(event: string, listener: (...args: any[]) => void): number {
    addListener(event, { listener });
    return getListenerCount(event);
  }

  function once(event: string, listener: (...args: any[]) => void): number {
    addListener(event, { listener, once: true });
    return getListenerCount(event);
  }

  function off(event: string, listener: (...args: any[]) => void): boolean {
    const eventListeners = listenersRegistry[event];
    if (eventListeners) {
      for (let i = 0; i < eventListeners.length; i++) {
        const l = eventListeners[i];
        if (l.listener === listener && (!l.once || !isCalledOnce(event, listener))) {
          eventListeners.splice(i, 1);
          // Reset index to re-evaluate remaining listeners
          i--;
        }
      }
    }

    return eventListeners.length > 0;
  }

  function emit(event: string, ...payload: any[]): any[] {
    const eventListeners = listenersRegistry[event] || [];

    return eventListeners.map((l) => l.listener(...payload));
  }

  function listenerCount(event: string): number {
    return (listenersRegistry[event]?.length ?? 0);
  }

  function getListenerCount(event: string) {
    if (ee.listeners?.[event]) {
      // eslint-disable-next-line dot-notation
      return ee["_events"][event].length;
    }
    return listenersRegistry[event]?.length || 0;
  }

  function addListener(event, options){
    let eventListeners = listenersRegistry[event];
    if (!listenersRegistry[event]) {
      eventListeners = [];
    }
    eventListeners.push(options);
    listenersRegistry[event] = eventListeners;

    ee.on(event, (...args) => emit(event, ...args));
  }

  function isCalledOnce(event, listener){
    const eventListeners = ee.listeners(event);

    let hasBeenCalled = false;
    eventListeners.every(l =>{
      if (l === listener) {
        // Call the once-listener (which removes the event handler itself in a subsequent tick).
        process.nextTick(() => emit(event), [listener]);
        l(...[]);
        return false;
      }
      return true;
    });

    return hasBeenCalled;
  }

  return { on, once, off, emit, listenerCount };
}

export { createEventEmitter };
