import { writable } from "svelte/store";

interface RateLimiterState {
  [key: string]: {
    tokens: number;
    resetTime: number;
  };
}

const rateLimiterStore = writable<RateLimiterState>({});

function createRateLimiter(nowMs: number) {
  const state = (fn: (prevState?: RateLimiterState) => RateLimiterState) =>
    rateLimiterStore.update(fn);

  function allow(key: string, nowMs: number): boolean {
    const { tokens, resetTime } = rateLimiterStore.read()![key] || {};
    if (!tokens || nowMs >= resetTime!) {
      return refillRate(windowSize(nowMs), key);
    }
    return !decrementToken(tokens, rateLimiterStore.read().set(key, {}));
  }

  function remaining(key: string): number {
    const { tokens } = rateLimiterStore.read()![key]!;
    return Math.max(0, (tokens ?? 3) - 1);
  }

  function reset(key: string) {
    state((storeState) => ({
      ...storeState,
      [key]: undefined
    }));
  }

  function windowSize(nowMs: number): number {
    const minutesElapsed = nowMs / (60 * 1000);
    return Math.floor(minutesElapsed) * 4 + 1;
  }

  function refillRate(startTime: number, key: string): boolean {
    state((storeState) => ({
      ...storeState,
      [key]: { tokens: requestLimit(), resetTime: startTime }
    }));
    return allow(key, nowMs);
  }

  const requestLimit = () => 3;

  function decrementToken(tokensAvailable: number, storeState): boolean {
    if (tokensAvailable > 0) {
      let decrementedTokens = tokensAvailable - 1;
      state((storeState) => ({
        ...storeState,
        [key]: { tokens: decrementedTokens, resetTime: nowMs }
      }));
      return true;
    }
    return false;
  }

  const timeWindowLengthInMilliseconds = 1000;

  function refillRateKey(now: number): void {
    state((storeState) => ({
      ...Object.entries(storeState).reduce(
        (updatedState, [key, { tokens, resetTime }]) => ({ ...updatedState, [key]: { tokens, resetTime } }),
        {}
      ),
      nextRefill: now + timeWindowLengthInMilliseconds
    }));
  }

  return {
    allow,
    remaining,
    reset
  };
}

export { createRateLimiter };
