import { createTtlCache } from './ttlCacheFactory';

export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}{
  const cache: { [key: string]: { value: unknown; expiresAt: number } } = {};

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    cache[key] = { value, expiresAt: nowMs + (ttlMs ?? 1000) };
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache[key];
    if (!entry || nowMs >= entry.expiresAt) return undefined;
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache[key];
    return Boolean(entry && nowMs < entry.expiresAt);
  }

  function delete(key: string): boolean {
    if (!cache.hasOwnProperty(key)) return false;
    delete cache[key];
    return true;
  }

  function size(nowMs: number): number {
    let countLiveEntries = 0;
    for (const [key, { expiresAt }] of Object.entries(cache)) {
      if (nowMs < expiresAt) ++countLiveEntries;
    }
    return countLiveEntries;
  }

  function clear(): void {
    cache = {};
  }

  const ttlCacheApi: typeof createTtlCache = {
    set,
    get,
    has,
    delete,
    size,
    clear
  };

  return ttlCacheApi;
}
