export function createTtlCache(): TtlCache {
  const map = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      const expiresAt = nowMs + (ttlMs === 0 ? 0 : ttlMs);
      map.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      const entry = map.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        map.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key, nowMs) {
      const entry = map.get(key);
      return Boolean(entry && nowMs < entry.expiresAt);
    },
    delete(key) {
      return map.delete(key);
    },
    size(nowMs) {
      return Array.from(map.entries()).filter(([_, entry]) => nowMs < entry.expiresAt).length;
    },
    clear() {
      map.clear();
    },
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
