function createEventEmitter() {
  const events = new Map<string, {
    once: Array<Function>
    normal: Array<Function>
  }>()

  function on(event: string, listener: Function): number {
    let eventMap = events.get(event)
    if (!eventMap) {
      eventMap = { once: [], normal: [] }
      events.set(event, eventMap)
    }
    eventMap.normal.push(listener)
    return eventMap.normal.length
  }

  function once(event: string, listener: Function): number {
    let eventMap = events.get(event)
    if (!eventMap) {
      eventMap = { once: [], normal: [] }
      events.set(event, eventMap)
    }
    eventMap.once.push(listener)
    return eventMap.once.length
  }

  function off(event: string, listener: Function): boolean {
    let eventMap = events.get(event)
    if (!eventMap) return false

    let index = eventMap.normal.indexOf(listener)
    if (index !== -1) {
      eventMap.normal.splice(index, 1)
      return true
    }

    index = eventMap.once.indexOf(listener)
    if (index !== -1) {
      eventMap.once.splice(index, 1)
      return true
    }

    return false
  }

  function emit(event: string, payload?: any): any[] {
    let eventMap = events.get(event)
    if (!eventMap) return []

    const results: any[] = []

    for (const listener of eventMap.normal) {
      results.push(listener.call(null, payload))
    }

    for (const listener of eventMap.once) {
      results.push(listener.call(null, payload))
    }

    eventMap.once.length = 0
    return results
  }

  function listenerCount(event: string): number {
    let eventMap = events.get(event)
    if (!eventMap) return 0
    return eventMap.normal.length + eventMap.once.length
  }

  return { on, once, off, emit, listenerCount }
}

export { createEventEmitter }
