export function createEventEmitter() {
    const listeners = new Map<string, Array<{ fn: (...args: any[]) => any; once: boolean }>>();

    function on(event: string, listener: (...args: any[]) => any): number {
        const arr = listeners.get(event) ?? [];
        arr.push({ fn: listener, once: false });
        listeners.set(event, arr);
        return arr.length;
    }

    function once(event: string, listener: (...args: any[]) => any): number {
        const arr = listeners.get(event) ?? [];
        arr.push({ fn: listener, once: true });
        listeners.set(event, arr);
        return arr.length;
    }

    function off(event: string, listener: (...args: any[]) => any): boolean {
        const arr = listeners.get(event)??[];
        const index = arr.findIndex(entry => entry.fn === listener);
        if (index !== -1) {
            arr.splice(index, 1);
            // Clean up empty arrays to keep map tidy
            if (arr.length === 0) listeners.delete(event);
            return true;
        }
        return false;
    }

    function emit(event: string, payload: any): any[] {
        const arr = listeners.get(event)??[];
        const results: any[] = [];
        // Iterate over a shallow copy to preserve order while removing one-time listeners
        for (const entry of [...arr]) {
            results.push(entry.fn(payload));
            if (entry.once) {
                const idx = arr.indexOf(entry);
                if (idx !== -1) arr.splice(idx, 1);
            }
        }
        // Clean up empty arrays after emission
        if (arr.length === 0) listeners.delete(event);
        return results;
    }

    function listenerCount(event: string): number {
        return listeners.get(event)?._length ?? 0; // using private length property for speed? Actually we need to access length:
    }
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, { listener: Listener; once: boolean }[]>();

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ listener, once: false });
      return listeners.get(event)!.length;
    },
    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ listener, once: true });
      return listeners.get(event)!.length;
    },
    off(event, listener) {
      const arr = listeners.get(event);
      if (!arr) return false;
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].listener === listener) {
          arr.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event, payload) {
      const arr = listeners.get(event);
      if (!arr || arr.length === 0) return [];
      const results: unknown[] = [];

      for (const entry of [...arr]) {
        results.push(entry.listener(payload));
        if (entry.once) {
          const idx = listeners.get(event)!.findIndex(e => e === entry);
          if (idx !== -1) {
            listeners.get(event)!.splice(idx, 1);
          }
        }
      }

      return results;
    },
    listenerCount(event) {
      const arr = listeners.get(event);
      return arr ? arr.length : 0;
    },
  };
}

export function createRateLimiter() {
    const LIMIT = 3;
    const WINDOW_MS = 1000;
    const state = new Map<string, { count: number; start: number }>();

    function getRecord(key: string, nowMs: number): { count: number; start: number } {
        let rec = state.get(key);
        if (!rec) {
            state.set(key, { count: 0, start: nowMs });
            return rec!;
        }
        if (nowMs - rec.start >= WINDOW_MS) {
            rec.count = 0;
            rec.start = nowMs;
        }
        return rec;
    }

    function allow(key: string, nowMs: number): boolean {
        const rec = getRecord(key, nowMs);
        if (rec.count < LIMIT) {
            rec.count++;
            return true;
        }
        return false;
    }

    function remaining(key: string, nowMs: number): number {
        const rec = getRecord(key, nowMs);
        const rem = LIMIT - rec.count;
        return rem > 0 ? rem : 0;
    }

    function reset(key: string): void {
        state.delete(key);
    }

    return { allow, remaining, reset };
}

export function createRateLimiter(): RateLimiter {
    const limit = 3;
    const windowMs = 1000;

    type Record = { count: number; start: number };
    const map = new Map<string, Record>();

    const getOrInit = (key: string, nowMs: number): Record => {
        let rec = map.get(key);
        if (!rec) {
            rec = { count: 0, start: nowMs };
            map.set(key, rec);
            return rec;
        }
        if (nowMs - rec.start >= windowMs) {
            // reset
            rec.count = 0;
            rec.start = nowMs;
        }
        return rec;
    };

    const rateLimiter: RateLimiter = {
        allow(key: string, nowMs: number): boolean {
            const rec = getOrInit(key, nowMs);
            if (rec(count < limit)) {
                rec.count++;
                return true;
            }
            return false;
        },
        remaining(key: string, nowMs: number): number {
            const rec = getOrInit(key, nowMs);
            return Math.max(limit - rec.count, 0);
        },
        reset(key: string): void {
            map.delete(key);
        }
    };

    return rateLimiter;
}

interface RateLimiter {
    allow(key: string, nowMs: number): boolean
    remaining(key: string, nowMs: number): number
    reset(key: string): void
}

