export function createTodoApp() {
    const todos: Todo[] = [];
    let nextId: number = 1;

    const addTodo = (text: string): Todo => {
        const todo: Todo = { id: nextId++, text, completed: false };
        todos.push(todo);
        return todo;
    };

    const getTodo = (id: number): Todo | undefined => {
        return todos.find(t => t.id === id);
    };

    const toggleTodo = (id: number): void => {
        const todo = getTodo(id);
        if (todo) {
            todo.completed = !todo.completed;
        }
    };

    const deleteTodo = (id: number): boolean => {
        const index = todos.findIndex(t => t.id === id);
        if (index !== -1) {
            todos.splice(index, 1);
            return true;
        }
        return false;
    };

    const listTodos = (): Todo[] => [
        ...todos,
    ];

    const listCompleted = (): Todo[] => {
        // Return a new array of completed todos
        return todos.filter(t => t.completed);
    };

    const listPending = (): Todo[] => {
        return todos.filter(t => !t.completed);
    };

    const clearCompleted = (): void => {
        for (let i = todos.length - 1; i >= 0; i--) {
            if (todos[i].completed) {
                todos.splice(i, 1);
            }
        }
    };

    return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}

export function createTodoApp(): TodoApp {
  let nextId = 1;
  const todoMap = new Map<number, Todo>();

  const addTodo = (text: string): Todo => {
    const todo: Todo = { id: nextId++, text, completed: false };
    todoMap.set(todo.id, todo);
    return todo;
  };

  const getTodo = (id: number): Todo | undefined => {
    return todoMap.get(id);
  };

  const toggleTodo = (id: number): void => {
    const todo = todoMap.get(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    return todoMap.delete(id);
  };

  const listTodos = (): Todo[] => {
    return Array.from(todoMap.values());
  };

  const listCompleted = (): Todo[] => {
    const completed: Todo[] = [];
    for (const todo of todoMap.values()) {
      if (todo.completed) completed.push(todo);
    }
    return completed;
  };

  const listPending = (): Todo[] => {
    const pending: Todo[] = [];
    for (const todo of todoMap.values()) {
      if (!todo.completed) pending.push(todo);
    }
    return pending;
  };

  const clearCompleted = (): void => {
    const idsToDelete: number[] = [];
    for (const todo of todoMap.values()) {
      if (todo.completed) idsToDelete.push(todo.id);
    }
    for (const id of idsToDelete) {
      todoMap.delete(id);
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}

