export function createRateLimiter() {
  const rateLimits = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const state = rateLimits.get(key) || { windowStart: nowMs, count: 0 };
      if (nowMs < state.windowStart + 1000) {
        state.count += 1;
      } else {
        state.windowStart = nowMs;
        state.count = 1;
      }
      return state.count <= 3;
    },
    remaining(key: string, nowMs: number): number {
      const state = rateLimits.get(key) || { windowStart: nowMs, count: 0 };
      return Math.max(0, 3 - state.count);
    },
    reset(key: string) {
      rateLimits.delete(key);
    }
  };
}
