export interface Calculator {
  currentValue: number;
  memory: number;

  add(n: number): this;
  subtract(n: number): this;
  multiply(n: number): this;
  divide(n: number): this;
  clear(): this;
  result(): number;
  memoryStore(): this;
  memoryAdd(): this;
  memoryClear(): this;
  memoryRecall(): number;
}

export function createCalculator(): Calculator {
  const calculator: Calculator = {
    currentValue: 0,
    memory: 0,

    add(n: number): this {
      this.currentValue += n;
      return this;
    },

    subtract(n: number): this {
      this.currentValue -= n;
      return this;
    },

    multiply(n: number): this {
      this.currentValue *= n;
      return this;
    },

    divide(n: number): this {
      if (n === 0) {
        throw new Error('Cannot divide by zero');
      }
      this.currentValue /= n;
      return this;
    },

    clear(): this {
      this.currentValue = 0;
      return this;
    },

    result(): number {
      return this.currentValue;
    },

    memoryStore(): this {
      this.memory = this.currentValue;
      return this;
    },

    memoryAdd(): this {
      this.memory += this.currentValue;
      return this;
    },

    memoryClear(): this {
      this.memory = 0;
      return this;
    },

    memoryRecall(): number {
      return this.memory;
    },
  };
  return calculator;
}
