export const createRateLimiter = (nowMs: number): Record<string, { allow: (key: string, nowMs: number) => void; remaining: (key: string, nowMs: number) => number; reset: (key: string) => void }> => {
  const rateLimiter = {
    count: 0,
    start: 0,
    windowDuration: 1000,
    keys: {} as Record<string, { count: number; start: number; windowDuration: number }>,
  };

  return {
    allow: (key: string, nowMs: number) => {
      if (nowMs < rateLimiter.start) {
        rateLimiter.start = nowMs;
        rateLimiter.count = 0;
      }
      if (nowMs - rateLimiter.start > rateLimiter.windowDuration) {
        rateLimiter.count = 0;
        rateLimiter.start = nowMs;
      }
      rateLimiter.count++;
      rateLimiter.keys[key] = {
        count: rateLimiter.count,
        start: rateLimiter.start,
        windowDuration: rateLimiter.windowDuration,
      };
    },
    remaining: (key: string, nowMs: number) => {
      const { count, start, windowDuration } = rateLimiter.keys[key] || {
        count: 0,
        start: 0,
        windowDuration: 0,
      };
      const elapsed = nowMs - start;
      const window = Math.floor(elapsed / windowDuration);
      return Math.max(count - window, 0);
    },
    reset: (key: string) => {
      if (rateLimiter.keys[key]) {
        rateLimiter.keys[key] = {
          count: 0,
          start: 0,
          windowDuration: 0,
        };
      }
    },
  };
};
