export function createRateLimiter() {
  const windowSize = 1000;
  const maxRequests = 3;
  const state: Map<string, { count: number; windowStart: number }> = new Map();

  function allow(key: string, nowMs: number): boolean {
    const entry = state.get(key);

    if (!entry || nowMs - entry.windowStart >= windowSize) {
      state.set(key, { count: 1, windowStart: nowMs });
      return true;
    }

    if (entry.count < maxRequests) {
      entry.count++;
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const entry = state.get(key);

    if (!entry || nowMs - entry.windowStart >= windowSize) {
      return maxRequests;
    }

    return Math.max(0, maxRequests - entry.count);
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, remaining, reset };
}
