type Listener = (...args: any[]) => any;
type Events = Record<string, { listeners: Listener[]; onceListeners: Listener[] }>;

export function createEventEmitter(): {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, ...payload: any[]): any[];
    listenerCount(event: string): number;
} {
    const events: Events = {};

    return {
        on(event, listener) {
            if (!events[event]) {
                events[event] = { listeners: [], onceListeners: [] };
            }
            events[event].listeners.push(listener);
            return events[event].listeners.length;
        },
        once(event, listener) {
            if (!events[event]) {
                events[event] = { listeners: [], onceListeners: [] };
            }
            events[event].onceListeners.push(listener);
            return events[event].onceListeners.length;
        },
        off(event, listener) {
            if (!events[event]) return false;
            const { listeners, onceListeners } = events[event];
            let removed = false;
            const newListeners = listeners.filter(l => {
                if (l === listener) {
                    removed = true;
                    return false;
                }
                return true;
            });
            const newOnceListeners = onceListeners.filter(l => {
                if (l === listener) {
                    removed = true;
                    return false;
                }
                return true;
            });
            events[event].listeners = newListeners;
            events[event].onceListeners = newOnceListeners;
            return removed;
        },
        emit(event, ...payload) {
            const results: any[] = [];
            if (events[event]) {
                const { listeners, onceListeners } = events[event];
                let newOnceListeners: Listener[] = [];
                for (const listener of listeners) {
                    results.push(listener(...payload));
                }
                for (let i = 0; i < onceListeners.length; i++) {
                    const listener = onceListeners[i];
                    results.push(listener(...payload));
                    if (i > 0 || newOnceListeners.length > 0) {
                        newOnceListeners.push(listener);
                    }
                }
                events[event].onceListeners = newOnceListeners;
            }
            return results;
        },
        listenerCount(event) {
            if (!events[event]) return 0;
            return events[event].listeners.length + events[event].onceListeners.length;
        }
    };
}
