export function createRateLimiter() {
  const state: Record<string, { count: number; startedMs: number }> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state[key];
      if (!entry) {
        state[key] = { count: 1, startedMs: nowMs };
        return true;
      }

      const { count, startedMs } = entry;
      const elapsed = nowMs - startedMs;

      if (elapsed >= 1000) {
        state[key] = { count: 1, startedMs: nowMs };
        return true;
      }

      if (count < 3) {
        state[key] = { count: count + 1, startedMs: startedMs };
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = state[key];
      if (!entry) return 3;

      const { count, startedMs } = entry;
      const elapsed = nowMs - startedMs;

      if (elapsed >= 1000) {
        return 3;
      }

      return Math.max(3 - count, 0);
    },

    reset(key: string): void {
      delete state[key];
    },
  };
}
