type Entry = {
    value: unknown;
    expiresAt: number;
};

export function createTtlCache(): TtlCache {
    const defaultTtlMs = 1000;
    const cache = new Map<string, Entry>();

    function set(key: string, value: unknown, nowMs: number, ttlMs: number = defaultTtlMs): void {
        const expiresAt = nowMs + ttlMs;
        cache.set(key, { value, expiresAt });
    }

    function get(key: string, nowMs: number): unknown {
        const entry = cache.get(key);
        if (entry && nowMs < entry.expiresAt) return entry.value;
        return undefined;
    }

    function has(key: string, nowMs: number): boolean {
        const entry = cache.get(key);
        return entry !== undefined && nowMs < entry.expiresAt;
    }

    function deleteEntry(key: string): boolean {
        return cache.delete(key);
    }

    function size(nowMs: number): number {
        let count = 0;
        for (const entry of cache.values()) {
            if (nowMs < entry.expiresAt) count++;
        }
        return count;
    }

    function clear(): void {
        cache.clear();
    }

    return {
        set,
        get,
        has,
        delete: deleteEntry,
        size,
        clear
    };
}

interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
    get(key: string, nowMs: number): unknown;
    has(key: string, nowMs: number): boolean;
    delete(key: string): boolean;
    size(nowMs: number): number;
    clear(): void;
}
