export function createTtlCache(): TtlCache {
    const cache: Map<string, { value: unknown; expiresAt: number }> = new Map();

    return {
        set(key: string, value: unknown, nowMs: number, ttlMs = 1000): void {
            if (ttlMs <= 0) {
                cache.delete(key);
                return;
            }
            cache.set(key, {
                value,
                expiresAt: nowMs + ttlMs
            });
        },

        get(key: string, nowMs: number): unknown {
            const entry = cache.get(key);
            if (!entry || nowMs >= entry.expiresAt) {
                return undefined;
            }
            return entry.value;
        },

        has(key: string, nowMs: number): boolean {
            const entry = cache.get(key);
            return !!entry && nowMs < entry.expiresAt;
        },

        delete(key: string): boolean {
            return cache.delete(key);
        },

        size(nowMs: number): number {
            return Array.from(cache.values()).filter(entry => nowMs < entry.expiresAt).length;
        },

        clear(): void {
            cache.clear();
        }
    };
}
