export function createCalculator() {
    let currentValue = 0;
    let memoryValue = 0;

    const add = (n: number) => {
        currentValue += n;
        return { currentValue, memoryValue };
    };

    const subtract = (n: number) => {
        currentValue -= n;
        return { currentValue, memoryValue };
    };

    const multiply = (n: number) => {
        currentValue *= n;
        return { currentValue, memoryValue };
    };

    const divide = (n: number) => {
        if (n === 0) throw new Error('Division by zero is not allowed.');
        currentValue /= n;
        return { currentValue, memoryValue };
    };

    const clear = () => {
        currentValue = 0;
        return { currentValue, memoryValue };
    };

    const result = () => currentValue;

    const storeMemory = () => {
        memoryValue = currentValue;
        return { currentValue, memoryValue };
    };

    const addToMemory = () => {
        memoryValue += currentValue;
        return { currentValue, memoryValue };
    };

    const clearMemory = () => {
        memoryValue = 0;
        return { currentValue, memoryValue };
    };

    const recallMemory = () => memoryValue;

    return {
        add: n => add(n),
        subtract: n => subtract(n),
        multiply: n => multiply(n),
        divide: n => divide(n),
        clear: clear,
        result: result,
        memoryStore: storeMemory,
        memoryAdd: addToMemory,
        memoryClear: clearMemory,
        memoryRecall: recallMemory
    };
