export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    if (ttlMs === undefined) {
      ttlMs = 1000;
    }
    cache.set(
      key,
      Object.assign(cache.get(key), { value, expiresAt: nowMs + ttlMs })
    );
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);
    if (!entry || nowMs >= entry.expiresAt) return undefined;
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    return Boolean(entry && nowMs < entry.expiresAt);
  }

  function delete(key: string): boolean {
    if (!cache.delete(key)) return false;
    return true;
  }

  function size(nowMs: number): number {
    let liveCount = 0;
    for (const [,, entry] of cache.entries()) {
      if (entry && nowMs < entry.expiresAt) {
        ++liveCount;
      }
    }
    return liveCount;
  }

  function clear(): void { cache.clear(); }

  const ttlCache: any = Object.assign(cache, ttlCache);
  ttlCache.set = set;
  ttlCache.get = get;
  ttlCache.has = has;
  ttlCache.delete = delete;
  ttlCache.size = size;
  ttlCache.clear = clear;

  return ttlCache;
}
