export function createTtlCache(): TtlCache {
  const cache: Map<string, { value: unknown; ttlMs: number }> = new Map();
  const DEFAULT_TTL_MS = 1000;

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    ttlMs = ttlMs ?? DEFAULT_TTL_MS;
    cache.set(key, { value, ttlMs });
  }

  function get(key: string, nowMs: number): unknown {
    const item = cache.get(key);
    if (!item || isExpired(nowMs)) return undefined;
    return item.value;
  }

  function has(key: string, nowMs: number): boolean {
    return !!get(key, nowMs);
  }

  function delete(key: string): boolean {
    return cache.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const item of cache.values()) if (!isExpired(nowMs)) ++count;
    return count;
  }

  function clear(): void {
    cache.clear();
  }

  function isExpired(nowMs: number) {
    const { ttlMs } = cache.get(key);
    return nowMs >= ttlMs ? true : false;
  }

  return {
    set,
    get,
    has,
    delete,
    size,
    clear
  };
}
