export function createEventEmitter(): {
  on: (event: string | symbol, listener: (...args: any[]) => any) => number
  once: (event: string | symbol, listener: (...args: any[]) => any) => number
  off: (event: string | symbol, listener: (...args: any[]) => any) => boolean
  emit: (event: string | symbol, ...args: any[]) => any[]
  listenerCount: (event: string | symbol) => number
} {
  const listeners = new Map<string | symbol, (...args: any[]) => any>()
  const onceListeners = new Map<string | symbol, (...args: any[]) => any>()

  function getListeners(event: string | symbol): Set<(...args: any[]) => any> {
    const result = new Set<(...args: any[]) => any>()
    const arrayListeners = listeners.get(event)
    if (Array.isArray(arrayListeners)) {
      for (const listener of arrayListeners) {
        result.add(listener)
      }
    }
    return result
  }

  const on = (event: string | symbol, listener: (...args: any[]) => any): number => {
    if (!listeners.has(event)) {
      listeners.set(event, [])
    }
    const arr = listeners.get(event)!
    if (Array.isArray(arr)) {
      arr.push(listener)
    } else {
      listeners.set(event, [listener])
    }
    return getListeners(event).size
  }

  const once = (event: string | symbol, listener: (...args: any[]) => any): number => {
    if (!onceListeners.has(event)) {
      onceListeners.set(event, [])
    }
    const arr = onceListeners.get(event)!
    if (Array.isArray(arr)) {
      arr.push(listener)
    } else {
      onceListeners.set(event, [listener])
    }
    const count = getListeners(event).size + (onceListeners.get(event)?.length ?? 0)
    return count
  }

  const off = (event: string | symbol, listener: (...args: any[]) => any): boolean => {
    const arr = listeners.get(event)
    if (arr && Array.isArray(arr)) {
      const idx = arr.indexOf(listener)
      if (idx !== -1) {
        arr.splice(idx, 1)
        return true
      }
    }

    const onceArr = onceListeners.get(event)
    if (onceArr && Array.isArray(onceArr)) {
      const idx = onceArr.indexOf(listener)
      if (idx !== -1) {
        onceArr.splice(idx, 1)
        return true
      }
    }
    return false
  }

  const emit = (event: string | symbol, ...args: any[]): any[] => {
    const normalListener = listeners.get(event)
    if (normalListener && Array.isArray(normalListener)) {
      const results: any[] = []
      for (const listener of normalListener) {
        const result = listener(...args)
        results.push(result)
      }
      return results
    }

    const onceListener = onceListeners.get(event)
    if (onceListener && Array.isArray(onceListener)) {
      const results: any[] = []
      for (const listener of onceListener) {
        const result = listener(...args)
        results.push(result)
        // Remove from once-listeners after being called
        const idx = onceListeners.get(event)?.indexOf(listener)
        if (idx !== -1) {
          const onceArr = onceListeners.get(event)!
          onceArr.splice(idx, 1)
        }
      }
      return results
    }

    return []
  }

  const listenerCount = (event: string | symbol): number => {
    let count = 0
    const arr = listeners.get(event)
    if (arr && Array.isArray(arr)) {
      count = arr.length
    }
    const onceArr = onceListeners.get(event)
    if (onceArr && Array.isArray(onceArr)) {
      count += onceArr.length
    }
    return count
  }

  return { on, once, off, emit, listenerCount }
}
