export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>()
  const defaultTtlMs = 1000

  return {
    set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
      const ttl = ttlMs ?? defaultTtlMs
      const expiresAt = nowMs + ttl
      store.set(key, {
        value,
        expiresAt
      })
    },

    get: (key: string, nowMs: number) => {
      const entry = store.get(key)
      if (!entry || nowMs >= entry.expiresAt) {
        store.delete(key)
        return undefined
      }
      return entry.value
    },

    has: (key: string, nowMs: number) => {
      const entry = store.get(key)
      if (!entry || nowMs >= entry.expiresAt) {
        return false
      }
      return true
    },

    delete: (key: string) => {
      return store.delete(key)
    },

    size: (nowMs: number) => {
      let count = 0
      for (const [key, entry] of store) {
        if (entry.expiresAt > nowMs) {
          count++
        }
      }
      return count
    },

    clear: () => {
      store.clear()
    }
  }
