export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = typeof ttlMs === 'number' ? ttlMs : 1000;
      store.set(key, { value, expiresAt: nowMs + ttl });
    },
    get(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs < entry.expiresAt) return entry.value;
      store.delete(key);
      return undefined;
    },
    has(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs < entry.expiresAt) return true;
      store.delete(key);
      return false;
    },
    delete(key) {
      return store.delete(key);
    },
    size(nowMs) {
      let count = 0;
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) ++count;
      }
      return count;
    },
    clear() {
      store.clear();
    }
  };
}

export function createTtlCache(): TtlCache {
  const DEFAULT_TTL_MS = 1000;
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = typeof ttlMs === 'number' ? (ttlMs ?? DEFAULT_TTL_MS) : DEFAULT_TTL_MS;
      store.set(key, { value, expiresAt: nowMs + ttl });
    },
    get(key: string, nowMs: number): unknown {
      const entry = store.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string): boolean {
      return store.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) count++;
      }
      // optional prune
      for (const [k, entry] of store.entries()) {
        if (nowMs >= entry.expiresAt) {
          store.delete(k);
        }
      }
      return count;
    },
    clear(): void {
      store.clear();
    },
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

