    on(event: string, listener: Function): number {
      eventListeners.set(event, [...eventListeners.get(event) || []]);
      eventListeners.get(event).push({ fn: listener, isOneTime: false });
      return eventListeners.get(event).length;
    },
    once(event: string, listener: Function): number {
