export function createTtlCache(): TtlCache {
  const cache = {};
  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      cache[key] = { value, nowMs, ttlMs };
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache[key];
      if (!entry || entry.nowMs > nowMs) return undefined;
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = cache[key];
      return entry !== undefined && entry.nowMs <= nowMs;
    },
    delete(key: string): boolean {
      const entry = cache[key];
      if (!entry) return false;
      delete cache[key];
      return true;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of Object.entries(cache)) {
        if (entry.nowMs <= nowMs) count++;
      }
      return count;
    },
    clear(): void {
      cache.clear();
    }
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}
